<?php
require_once __DIR__.'/../lib/app.php';$pageTitle='부서관리';include '_top.php';require_hr_admin();$pdo=db();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($action==='delete'){$pdo->prepare('DELETE FROM departments WHERE id=?')->execute([$id]);$msg='삭제되었습니다.';}else{$data=[trim($_POST['code']??'')?:null,trim($_POST['name']??''),($_POST['parent_id']??'')!==''?(int)$_POST['parent_id']:null,($_POST['manager_employee_id']??'')!==''?(int)$_POST['manager_employee_id']:null,(int)($_POST['sort_order']??0),isset($_POST['is_active'])?1:0,trim($_POST['memo']??'')];if(!$data[1])throw new Exception('부서명을 입력하세요.');if($id){$pdo->prepare('UPDATE departments SET code=?,name=?,parent_id=?,manager_employee_id=?,sort_order=?,is_active=?,memo=? WHERE id=?')->execute([...$data,$id]);}else{$pdo->prepare('INSERT INTO departments(code,name,parent_id,manager_employee_id,sort_order,is_active,memo) VALUES(?,?,?,?,?,?,?)')->execute($data);}$msg='저장되었습니다.';}}catch(Throwable $e){$err=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM departments WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$departments=$pdo->query("SELECT d.*,p.name parent_name,e.name manager_name,(SELECT COUNT(*) FROM employees x WHERE x.department_id=d.id AND x.is_active=1) employee_count FROM departments d LEFT JOIN departments p ON p.id=d.parent_id LEFT JOIN employees e ON e.id=d.manager_employee_id ORDER BY d.sort_order,d.id")->fetchAll();$employees=$pdo->query("SELECT id,name,position FROM employees WHERE is_active=1 ORDER BY sort_order,id")->fetchAll();
?><div class="page-title-row"><div><h1>부서관리</h1><p class="page-desc">조직의 부서를 등록하고 부서장과 표시순서를 관리합니다.</p></div></div><?php if($msg):?><div class="alert ok"><?=h($msg)?></div><?php endif?><?php if($err):?><div class="alert err"><?=h($err)?></div><?php endif?><div class="two-panel"><section class="card"><h2><?=$edit?'부서 수정':'부서 등록'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><div class="form-grid cols-2"><label>부서코드<input name="code" value="<?=h($edit['code']??'')?>" placeholder="예: LOAN"></label><label>부서명<input name="name" required value="<?=h($edit['name']??'')?>"></label><label>상위부서<select name="parent_id"><option value="">없음</option><?php foreach($departments as $d):if(($edit['id']??0)==$d['id'])continue;?><option value="<?=$d['id']?>" <?=($edit['parent_id']??'')==$d['id']?'selected':''?>><?=h($d['name'])?></option><?php endforeach?></select></label><label>부서장<select name="manager_employee_id"><option value="">미지정</option><?php foreach($employees as $e):?><option value="<?=$e['id']?>" <?=($edit['manager_employee_id']??'')==$e['id']?'selected':''?>><?=h($e['name'].' '.$e['position'])?></option><?php endforeach?></select></label><label>표시순서<input type="number" name="sort_order" value="<?=h($edit['sort_order']??0)?>"></label><label class="toggle-row"><input type="checkbox" name="is_active" <?=!$edit||$edit['is_active']?'checked':''?>><span><strong>사용 중</strong></span></label><label class="span-2">비고<input name="memo" value="<?=h($edit['memo']??'')?>"></label></div><div class="form-actions"><button class="btn">저장</button><?php if($edit):?><a class="btn gray" href="departments.php">취소</a><?php endif?></div></form></section><section class="card"><h2>부서 목록</h2><div class="table-wrap"><table class="table"><tr><th>순서</th><th>부서</th><th>상위부서</th><th>부서장</th><th>직원</th><th>관리</th></tr><?php foreach($departments as $d):?><tr><td><?=$d['sort_order']?></td><td><strong><?=h($d['name'])?></strong><div class="muted"><?=h($d['code'])?></div></td><td><?=h($d['parent_name']?:'-')?></td><td><?=h($d['manager_name']?:'-')?></td><td><?=$d['employee_count']?>명</td><td><a class="btn sm ghost" href="?edit=<?=$d['id']?>">수정</a></td></tr><?php endforeach?></table></div></section></div><?php include '_bottom.php';?>